      "vraag": "Kan een benadeelde zijn vordering uit hoofde van mijnbouwschade óók op art. 6:162 BW baseren, terwijl er een risicoaansprakelijkheid op grond van art. 6:177 BW beschikbaar is?",
      "antwoord": "Ja. Ondanks de ruime toerekening die plaatsvindt bij aansprakelijkheid op grond van art. 6:177 BW, kan de vordering (ook) op grond van art. 6:162 BW worden beoordeeld wanneer dat voor de benadeelde tot een gunstiger resultaat leidt. De twee grondslagen sluiten elkaar niet uit.",
