      "antwoord": "Als een norm specifiek strekt ter bescherming tegen een bepaald gevaar en dat gevaar zich heeft verwezenlijkt, moet de rechter bij onzekerheid over het condicio-sine-qua-non-verband tussen normschending en schade de omkeringsregel toepassen.",
